<?php
require_once __DIR__.'/includes/member_auth.php';
$page_title='My Borrowed Books';$page_subtitle='Books grouped by transaction, with individual due dates and return details';
$member=current_member();$memberId=(int)current_member_id();
$search=mb_substr(trim((string)($_GET['q']??'')),0,100);$tab=($_GET['tab']??'current')==='history'?'history':'current';
$where='l.BorrowerUserID=?';$params=[$memberId];
$where.=$tab==='current'?" AND EXISTS(SELECT 1 FROM loan_detail d LEFT JOIN return_detail rd ON rd.LoanDetailID=d.LoanDetailID WHERE d.LoanID=l.LoanID AND rd.ReturnDetailID IS NULL)":" AND EXISTS(SELECT 1 FROM loan_detail d JOIN return_detail rd ON rd.LoanDetailID=d.LoanDetailID WHERE d.LoanID=l.LoanID)";
if($search!==''){$where.=" AND (CAST(l.LoanID AS CHAR) LIKE ? OR EXISTS(SELECT 1 FROM loan_detail d JOIN book_copy c ON c.CopyID=d.CopyID JOIN book b ON b.BookID=c.BookID WHERE d.LoanID=l.LoanID AND (b.Title LIKE ? OR c.AccessionNumber LIKE ?)))";array_push($params,...array_fill(0,3,'%'.$search.'%'));}
$pg=pagination_calc((int)fetch_value("SELECT COUNT(*) FROM loan l WHERE $where",$params),10,pagination_page());
$loans=fetch_all("SELECT l.* FROM loan l WHERE $where ORDER BY l.LoanID DESC LIMIT {$pg['per_page']} OFFSET {$pg['offset']}",$params);
require __DIR__.'/includes/member_layout_top.php';?>
<div class="page-toolbar"><form method="get" class="d-flex flex-wrap gap-2"><input name="q" type="search" class="form-control" value="<?= h($search) ?>" placeholder="Transaction number, title or accession" aria-label="Search my borrowed books"><select name="tab" class="form-select" aria-label="Borrowed books list"><option value="current">Currently borrowed</option><option value="history" <?= $tab==='history'?'selected':'' ?>>Return history</option></select><button class="btn btn-primary">Search</button><a class="btn btn-outline-secondary" href="my_borrowed_books.php">Clear</a></form></div>
<p class="small"><?= pagination_info($pg) ?> borrowing transactions. Partial returns remain grouped with their original transaction.</p>
<?php if(!$loans):?><div class="card transaction-card p-4">No matching borrowing records.</div><?php endif;?>
<?php foreach($loans as $l):$items=fetch_all("SELECT d.*,b.Title,c.AccessionNumber,rd.ReturnDate,rd.ReturnCondition,rh.ReturnBatchID,(SELECT COALESCE(SUM(f.FineAmount),0) FROM fine f WHERE f.LoanDetailID=d.LoanDetailID) AS FineTotal FROM loan_detail d JOIN book_copy c ON c.CopyID=d.CopyID JOIN book b ON b.BookID=c.BookID LEFT JOIN return_detail rd ON rd.LoanDetailID=d.LoanDetailID LEFT JOIN return_header rh ON rh.ReturnID=rd.ReturnID WHERE d.LoanID=? ORDER BY d.LoanDetailID",[$l['LoanID']]);?>
<details class="card transaction-card mb-3" <?= $search!==''?'open':'' ?>><summary class="p-3" style="cursor:pointer"><strong>Transaction #<?= (int)$l['LoanID'] ?></strong> · <?= fmt_datetime($l['LoanDate']) ?> · <?= count($items) ?> book(s) <span class="small text-decoration-underline">View books</span></summary><div class="px-3 table-responsive"><table class="table"><thead><tr><th>Book / accession</th><th>Due date</th><th>Status</th><th>Return details</th><th>Assessed penalties</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?= h($it['Title']) ?><div class="small text-muted"><?= h($it['AccessionNumber']) ?></div></td><td><?= fmt_date($it['DueDate']) ?></td><td><?= status_badge($it['ReturnDate']?'Returned':(is_overdue($it['DueDate'])?'Overdue':'Borrowed')) ?></td><td><?php if($it['ReturnDate']):?><?= fmt_datetime($it['ReturnDate']) ?> · <?= h($it['ReturnCondition']) ?><div class="small"><?= h(return_batch_ref((int)$it['ReturnBatchID'])) ?></div><?php else:?>Not returned<?php endif;?></td><td><?= money($it['FineTotal']) ?></td></tr><?php endforeach;?></tbody></table></div></details><?php endforeach;?>
<?= pagination_links($pg,$_GET) ?>
<?php require __DIR__.'/includes/member_layout_bottom.php'; ?>
